{{--
    THE TIME DEAL STRIP (Lane TDS) -- App\Services\TimeDealStrip. Appearance -> Time deal strip.
    Lane TDS2: the thin bar the owner pointed at ("make our top strip like this, thin and similar, and by changing
    brands names continuously"): T2 Holographic on computers, M5 Chips on phones, in the shop's own Outfit. Every size is a clamp() of the viewport,
    so it shrinks with the screen instead of colliding; at the very narrowest the words end in "…" rather than ever
    running under the clock. Not sticky: it scrolls away above the sticky header. Printed only when on and not yet
    over, so off means not one byte of it on the page. No layout is measured; the script only writes three numbers
    once a second and stops at zero.
--}}@php($kbbTds = app(\App\Services\TimeDealStrip::class)->view())
<style>{!! \App\Services\TimeDealStrip::CSS !!}</style>
<div class="kdt{{ $kbbTds['phone'] ? '' : ' kdt-np' }}{{ $kbbTds['desktop'] ? '' : ' kdt-nd' }}{{ $kbbTds['motion'] ? '' : ' kdt-still' }}" id="kbb-tds" dir="{{ $kbbTds['rtl'] ? 'rtl' : 'ltr' }}" data-end="{{ $kbbTds['end'] }}" data-daily="{{ $kbbTds['daily'] ? '1' : '0' }}"><a class="kdt-a" href="{{ $kbbTds['href'] }}" aria-label="{{ $kbbTds['button'] !== '' ? $kbbTds['button'] : $kbbTds['heading'] }}"></a>@if ($kbbTds['chip'] !== '')<span class="kdt-chip">{{ $kbbTds['chip'] }}</span>@endif @if ($kbbTds['offer'] !== '')<em class="kdt-off">{{ $kbbTds['offer'] }}</em>@endif<span class="kdt-clk" role="timer"><b data-u>{{ sprintf('%02d', intdiv($kbbTds['left'], 3600)) }}</b><small>{{ $kbbTds['units'][0] }}</small><b data-u>{{ sprintf('%02d', intdiv($kbbTds['left'], 60) % 60) }}</b><small>{{ $kbbTds['units'][1] }}</small><b data-u>{{ sprintf('%02d', $kbbTds['left'] % 60) }}</b><small>{{ $kbbTds['units'][2] }}</small></span>@if ($kbbTds['heading'] !== '')<span class="kdt-pill">{{ $kbbTds['heading'] }}</span>@endif @if ($kbbTds['brands'] !== [])<span class="kdt-txt">@if ($kbbTds['sub'] !== '')<span class="kdt-lead">{{ $kbbTds['sub'] }}</span>@endif @if ($kbbTds['short'] !== '')<span class="kdt-ls">{{ $kbbTds['short'] }}</span>@endif<span class="kdt-rot">@foreach ($kbbTds['brands'] as $kbbTdsI => $kbbTdsB)<span{!! $kbbTdsI === 0 ? ' class="on"' : '' !!}>{{ $kbbTdsB }}</span>@endforeach</span></span>@endif @if ($kbbTds['button'] !== '')<a class="kdt-go" href="{{ $kbbTds['href'] }}">{{ $kbbTds['button'] }}</a>@endif @if ($kbbTds['closable'])<button type="button" class="kdt-x" data-kds-x aria-label="{{ $kbbTds['rtl'] ? 'إغلاق' : 'Close' }}"><svg viewBox="0 0 12 12" width="11" height="11" aria-hidden="true"><path d="M2 2l8 8M10 2l-8 8" stroke="currentColor" stroke-width="1.8" stroke-linecap="round"/></svg></button>@endif</div>
<script>(function(){var s=document.getElementById('kbb-tds');if(!s)return;var k='kbbTds'+s.dataset.end,x=s.querySelector('[data-kds-x]'),i;try{if(sessionStorage.getItem(k)){s.remove();return}}catch(_){}if(x)x.addEventListener('click',function(){try{sessionStorage.setItem(k,'1')}catch(_){}clearInterval(i);s.remove()});var e=+s.dataset.end,d=s.dataset.daily==='1',D=864e5,b=s.querySelectorAll('[data-u]'),r=s.querySelectorAll('.kdt-rot>span'),c=0,n=0;function p(v){return(v<10?'0':'')+v}function t(){var w=Date.now(),l=e-w;if(l<=0){if(!d){clearInterval(i);s.remove();return}while(e<=w)e+=D;l=e-w}var q=Math.floor(l/1e3);b[0].textContent=p(Math.floor(q/3600));b[1].textContent=p(Math.floor(q/60)%60);b[2].textContent=p(q%60);if(r.length>1&&++n%2===0){r.forEach(function(z){z.classList.remove('out')});r[c].classList.remove('on');r[c].classList.add('out');c=(c+1)%r.length;r[c].classList.add('on')}}i=setInterval(t,1e3);t()})()</script>
